91: int32_t DBinderCallbackStub::ProcessProto(uint32_t code, MessageParcel &data, MessageParcel &reply,
92:     MessageOption &option)
93: {
94:     int uid = IPCSkeleton::GetCallingUid();
95:     int pid = IPCSkeleton::GetCallingPid();
96:     if (uid < 0 || pid < 0) {
97:         ZLOGE(LOG_LABEL, "uid or pid err");
98:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_GET_UID_OR_PID_FAIL, __FUNCTION__);
99:         return DBINDER_SERVICE_PROCESS_PROTO_ERR;
100:     }
101:     if (IPCProcessSkeleton::GetCurrent() == nullptr) {
102:         ZLOGE(LOG_LABEL, "IPCProcessSkeleton GetCurrent is null");
103:         return ERR_NULL_OBJECT;
104:     }
105:     sptr<IRemoteObject> object = IPCProcessSkeleton::GetCurrent()->GetSAMgrObject();
106:     if (object == nullptr) {
107:         ZLOGE(LOG_LABEL, "get sa object is null");
108:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_GET_SA_OBJECT_NULL, __FUNCTION__);
109:         return DBINDER_CALLBACK_READ_OBJECT_ERR;
110:     }
111:     IPCObjectProxy *samgr = reinterpret_cast<IPCObjectProxy *>(object.GetRefPtr());
112:     std::string sessionName = samgr->GetSessionNameForPidUid(uid, pid);
113:     if (sessionName.empty()) {
114:         ZLOGE(LOG_LABEL, "grans session name failed");
115:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_GET_SESSION_NAME_FAIL, __FUNCTION__);
116:         return DBINDER_SERVICE_WRONG_SESSION;
117:     }
118:     return ProcessData(uid, pid, sessionName, data, reply);
119: }
