121: int32_t DBinderCallbackStub::ProcessData(int uid, int pid, const std::string &sessionName, MessageParcel &data,
122:     MessageParcel &reply)
123: {
124:     MessageParcel authData;
125:     MessageParcel authReply;
126:     MessageOption authOption;
127:     if (!authData.WriteUint32(pid) || !authData.WriteUint32(uid) || !authData.WriteString(localDeviceID_) ||
128:         !authData.WriteUint64(stubIndex_) || !authData.WriteUint32(tokenId_)) {
129:         ZLOGE(LOG_LABEL, "write to MessageParcel fail");
130:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_ERR_INVALID_DATA, __FUNCTION__);
131:         return ERR_INVALID_DATA;
132:     }
133:     IRemoteInvoker *dbinderInvoker = IPCThreadSkeleton::GetRemoteInvoker(IRemoteObject::IF_PROT_DATABUS);
134:     if (dbinderInvoker == nullptr) {
135:         ZLOGE(LOG_LABEL, "no databus thread and invoker");
136:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_RPC_DATABUS_INVOKER_ERR, __FUNCTION__);
137:         return RPC_DATABUS_INVOKER_ERR;
138:     }
139:     int err = dbinderInvoker->SendRequest(handle_, DBINDER_ADD_COMMAUTH, authData, authReply, authOption);
140:     if (err != ERR_NONE) {
141:         ZLOGE(LOG_LABEL, "send auth info to remote fail");
142:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_BINDER_CALLBACK_AUTHCOMM_ERR, __FUNCTION__);
143:         return BINDER_CALLBACK_AUTHCOMM_ERR;
144:     }
145:     ZLOGI(LOG_LABEL, "send to stub ok! stubIndex:%{public}" PRIu64 " peerDevice:%{public}s localDeviceID:%{public}s "
146:         "serviceName:%{public}s uid:%{public}d pid:%{public}d tokenId:%{public}u sessionName:%{public}s",
147:         stubIndex_, IPCProcessSkeleton::ConvertToSecureString(deviceID_).c_str(),
148:         IPCProcessSkeleton::ConvertToSecureString(localDeviceID_).c_str(), serviceName_.c_str(), uid, pid, tokenId_,
149:         sessionName.c_str());
150:     if (!reply.WriteUint32(IRemoteObject::IF_PROT_DATABUS) || !reply.WriteUint64(stubIndex_) ||
151:         !reply.WriteString(serviceName_) || !reply.WriteString(deviceID_) || !reply.WriteString(localDeviceID_) ||
152:         !reply.WriteString(sessionName) || !reply.WriteUint32(tokenId_)) {
153:         ZLOGE(LOG_LABEL, "write to parcel fail");
154:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_ERR_INVALID_DATA, __FUNCTION__);
155:         return ERR_INVALID_DATA;
156:     }
157:     return 0;
158: }

393: int IPCObjectStub::SendRequestInner(uint32_t code, MessageParcel &data, MessageParcel &reply, MessageOption &option)
394: {
395:     int result = ERR_NONE;
396:     std::unique_lock<std::recursive_mutex> lockGuard(serialRecursiveMutex_, std::defer_lock);
397:     if (serialInvokeFlag_) {
398:         lockGuard.lock();
399:     }
400: #ifdef ENABLE_IPC_TRACE
401:     bool isTraceEnable = IPCTrace::IsEnabled();
402:     if (isTraceEnable) {
403:         IPCTrace::Start(GenOnRemoteRequestTraceInfo(code));
404:     }
405: #endif
406:     auto start = std::chrono::steady_clock::now();
407:     lastRequestTime_ = static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
408:         start.time_since_epoch()).count());
409:     result = OnRemoteRequest(code, data, reply, option);
410:     auto finish = std::chrono::steady_clock::now();

439: int IPCObjectStub::SendRequest(uint32_t code, MessageParcel &data, MessageParcel &reply, MessageOption &option)
440: {
441:     switch (code) {
442:         case PING_TRANSACTION:
443:             return DBinderPingTransaction(code, data, reply, option);
444:         case INTERFACE_TRANSACTION:
445:             return DBinderSearchDescriptor(code, data, reply, option);
446:         case SYNCHRONIZE_REFERENCE:
447:             return DBinderSearchRefCount(code, data, reply, option);
448:         case DUMP_TRANSACTION:
449:             return DBinderDumpTransaction(code, data, reply, option);
450:         case GET_PROTO_INFO:
451:             return ProcessProto(code, data, reply, option);
452: #ifndef CONFIG_IPC_SINGLE
453:         case INVOKE_LISTEN_THREAD:
454:             return DBinderInvokeListenThread(code, data, reply, option);
455:         case DBINDER_INCREFS_TRANSACTION:
456:             return DBinderIncRefsTransaction(code, data, reply, option);
457:         case DBINDER_DECREFS_TRANSACTION:
458:             return DBinderDecRefsTransaction(code, data, reply, option);
459:         case DBINDER_ADD_COMMAUTH:
460:             return DBinderAddCommAuth(code, data, reply, option);
461:         case GET_SESSION_NAME:
462:             return DBinderGetSessionName(code, data, reply, option);
463:         case GET_GRANTED_SESSION_NAME:
464:             return DBinderGetGrantedSessionName(code, data, reply, option);
465:         case GET_SESSION_NAME_PID_UID:
466:             return DBinderGetSessionNameForPidUid(code, data, reply, option);
467:         case GET_PID_UID:
468:             return DBinderGetPidUid(code, data, reply, option);
469:         case REMOVE_SESSION_NAME:
470:             return DBinderRemoveSessionName(code, data, reply, option);
471:         case CLEAR_DBINDER_SERVICE_STATE:
472:             return DBinderClearServiceState(code, data, reply, option);
473: #endif
474:         default:
475:             return SendRequestInner(code, data, reply, option);
476:     }
477:     return ERR_NONE;

299: int IPCObjectStub::DBinderAddCommAuth(uint32_t code, MessageParcel &data, MessageParcel &reply, MessageOption &option)
300: {
301:     if (IPCSkeleton::IsLocalCalling()) {
302:         ZLOGE(LABEL, "DBINDER_ADD_COMMAUTH is not supported in ipc communication, desc:%{public}s",
303:             remoteDescriptor_.c_str());
304:         return IPC_STUB_INVALID_DATA_ERR;
305:     }
306: 
307:     DBinderDatabusInvoker *invoker = reinterpret_cast<DBinderDatabusInvoker *>(
308:         IPCThreadSkeleton::GetRemoteInvoker(IRemoteObject::IF_PROT_DATABUS));
309:     if (invoker == nullptr) {
310:         ZLOGE(LABEL, "get dbinder databus invoker failed");
311:         return IPC_STUB_INVALID_DATA_ERR;
312:     }
313: 
314:     uid_t uid = invoker->GetCallerUid();
315:     if (uid >= ALLOWED_UID) {
316:         ZLOGE(LABEL, "DBINDER_ADD_COMMAUTH unauthenticated user, desc:%{public}s, uid:%{public}u",
317:             remoteDescriptor_.c_str(), uid);
318:         return IPC_STUB_INVALID_DATA_ERR;
319:     }
320:     return AddAuthInfo(data, reply, code);
321: }
